let track_outbound_links=(i={})=>{var t=new URL(pixel_url_base);let l=t.hostname,o=t.pathname.replace(/\/$/,"");document.querySelectorAll("a").forEach(t=>{var e=t.getAttribute("href");let r=t.innerText.trim()||t.getAttribute("title")||t.getAttribute("data-original-title")||t.getAttribute("aria-label");if(e&&"#"!=e){let a;try{a=new URL(e,window.location.origin)}catch(t){return}var e=a.hostname!==l,n=a.hostname===l&&!a.pathname.startsWith(o);(e||n)&&t.addEventListener("click",t=>{var e={type:"outbound_click",outbound_url:a.href,outbound_title:r,url:window.location.href,...i};send_data_beacon(e)})}})};